function f2(e) {
  let t = [];
  if (!e || e.length === 0)
    return { ok: !1, errors: [`至少需要保留 1 个评级档位`] };
  for (let n of e)
    n.min == null
      ? t.push(`「${n.label || n.level}」分值区间不完整`)
      : n.max != null &&
        n.min > n.max &&
        t.push(`「${n.label || n.level}」最低分不能大于最高分`);
  if (t.length) return { ok: !1, errors: t };
  let n = [...e].sort((e, t) => e.min - t.min);
  n[0].min !== 0 &&
    t.push(`分值未从 0 开始（当前最低档「${n[0].label}」起点为 ${n[0].min}）`);
  for (let e = 1; e < n.length; e += 1) {
    let r = n[e - 1],
      i = n[e];
    if (r.max == null) {
      t.push(`「${r.label}」已无上限，后续「${i.label}」无法生效`);
      continue;
    }
    i.min <= r.max
      ? t.push(`「${r.label}」与「${i.label}」区间重叠（${i.min} ≤ ${r.max}）`)
      : i.min !== r.max + 1 &&
        t.push(
          `「${r.label}」与「${i.label}」之间存在遗漏区间（${r.max + 1} ~ ${i.min - 1} 无归属）`,
        );
  }
  let r = n.slice(0, -1).find((e) => e.max == null);
  return (
    r && t.push(`只有最高分档可以设置为无上限（当前「${r.label}」无上限）`),
    { ok: t.length === 0, errors: t }
  );
}
